from pathlib import Path
import re

path = Path('/home/ubuntu/trezo-smart-treasury/client/src/pages/Workspace.tsx')
text = path.read_text()
new_function = r'''function RequestWorkflow({ rows, currencies, companies, beneficiaries, channels, operationalRoles, isAdmin, onCreateRequest, onOpenRequest }: { rows: Array<{ id: number; referenceNumber: string; title: string; amount: string; currency: string; status: string; companyId?: number; beneficiaryId?: number; channelId?: number; scheduledFor?: Date | null; createdAt?: Date }>; currencies: CurrencyDefinition[]; companies: Array<{ id: number; name: string }>; beneficiaries: Array<{ id: number; name: string; companyId: number }>; channels: Array<{ id: number; name: string }>; operationalRoles: string[]; isAdmin: boolean; onCreateRequest: () => void; onOpenRequest: (requestId: number) => void }) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [companyFilter, setCompanyFilter] = useState("all");
  const [beneficiaryFilter, setBeneficiaryFilter] = useState("all");
  const [channelFilter, setChannelFilter] = useState("all");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const companyName = (id?: number) => companies.find((item) => item.id === id)?.name ?? "غير محدد";
  const beneficiaryName = (id?: number) => beneficiaries.find((item) => item.id === id)?.name ?? "غير محدد";
  const channelName = (id?: number) => channels.find((item) => item.id === id)?.name ?? "غير محدد";
  const statusLabels: Record<string, string> = { draft: "مسودة", review: "قيد المراجعة", approved: "معتمد", executed: "منفذ", rejected: "مرفوض" };
  const filteredRows = rows.filter((row) => {
    const term = search.trim().toLocaleLowerCase();
    const haystack = `${row.title} ${row.referenceNumber} ${row.currency} ${companyName(row.companyId)} ${beneficiaryName(row.beneficiaryId)} ${channelName(row.channelId)}`.toLocaleLowerCase();
    const requestDate = new Date(row.scheduledFor ?? row.createdAt ?? 0);
    return (!term || haystack.includes(term)) && (statusFilter === "all" || row.status === statusFilter) && (companyFilter === "all" || String(row.companyId) === companyFilter) && (beneficiaryFilter === "all" || String(row.beneficiaryId) === beneficiaryFilter) && (channelFilter === "all" || String(row.channelId) === channelFilter) && (!fromDate || requestDate >= new Date(`${fromDate}T00:00:00`)) && (!toDate || requestDate <= new Date(`${toDate}T23:59:59`));
  });
  const hasFilters = Boolean(search.trim() || fromDate || toDate) || [statusFilter, companyFilter, beneficiaryFilter, channelFilter].some((value) => value !== "all");
  const clearFilters = () => { setSearch(""); setStatusFilter("all"); setCompanyFilter("all"); setBeneficiaryFilter("all"); setChannelFilter("all"); setFromDate(""); setToDate(""); };
  const utils = trpc.useUtils();
  const [selectedRequestId, setSelectedRequestId] = useState<number>();
  const [file, setFile] = useState<File | null>(null);
  const [attachmentMessage, setAttachmentMessage] = useState("");
  const transition = trpc.requests.transition.useMutation({ onSuccess: () => void utils.requests.list.invalidate() });
  const attachments = trpc.attachments.list.useQuery({ requestId: selectedRequestId ?? 0 }, { enabled: Boolean(selectedRequestId) });
  const upload = trpc.attachments.upload.useMutation({ onSuccess: () => { setFile(null); setAttachmentMessage("تم رفع المرفق بنجاح"); void attachments.refetch(); }, onError: (error) => setAttachmentMessage(error.message) });
  const download = trpc.attachments.download.useMutation({ onError: (error) => setAttachmentMessage(error.message) });
  const next: Record<string, { label: string; status: "draft" | "review" | "approved" | "executed" | "rejected" } | undefined> = { draft: { label: "إرسال للمراجعة", status: "review" }, review: { label: "اعتماد المدير المالي", status: "approved" }, approved: { label: "تسجيل التنفيذ", status: "executed" }, rejected: { label: "إعادة فتح المسودة", status: "draft" } };
  const reviewerAction = { label: "تأكيد المراجعة", status: "review" as const };
  const canCreate = isAdmin || operationalRoles.includes("accountant");
  const canReview = isAdmin || operationalRoles.includes("reviewer");
  const canApprove = isAdmin || operationalRoles.includes("cfo");
  const canExecute = isAdmin || operationalRoles.includes("gm") || operationalRoles.includes("cfo");
  const canReopen = isAdmin || operationalRoles.includes("accountant") || operationalRoles.includes("reviewer");
  const openAttachment = async (attachmentId: number, fileName: string, shouldDownload: boolean) => { try { const result = await download.mutateAsync({ attachmentId }); const link = document.createElement("a"); link.href = result.url; link.target = shouldDownload ? "_self" : "_blank"; if (shouldDownload) link.download = fileName; link.rel = "noreferrer"; document.body.appendChild(link); link.click(); link.remove(); } catch { /* mutation exposes the localized error in the panel */ } };
  const uploadFile = () => { if (!selectedRequestId || !file) return; const reader = new FileReader(); reader.onload = () => { const base64 = typeof reader.result === "string" ? reader.result : ""; if (base64) upload.mutate({ requestId: selectedRequestId, fileName: file.name, mimeType: file.type || "application/octet-stream", sizeBytes: file.size, base64 }); }; reader.readAsDataURL(file); };
  return <div className="overflow-hidden rounded-2xl border bg-card"><div className="border-b p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div><h3 className="font-display text-lg font-extrabold">قائمة طلبات الصرف</h3><p className="mt-1 text-xs text-muted-foreground">عرض تشغيلي مرتب مع فلاتر الشركة والمستفيد وقناة الصرف والتاريخ.</p></div>{canCreate && <button onClick={onCreateRequest} className="inline-flex items-center justify-center gap-2 rounded-xl bg-secondary px-4 py-2.5 text-xs font-bold text-primary"><Plus size={15}/> طلب جديد</button>}</div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4"><label className="flex items-center gap-2 rounded-xl border bg-background px-3 py-2.5 md:col-span-2 xl:col-span-2"><Search size={16} className="text-muted-foreground"/><input value={search} onChange={(event) => setSearch(event.target.value)} className="min-w-0 flex-1 bg-transparent text-sm outline-none" placeholder="ابحث بالرقم أو البيان أو المستفيد أو الشركة" aria-label="البحث في طلبات الصرف"/></label><select value={companyFilter} onChange={(event) => setCompanyFilter(event.target.value)} className="rounded-xl border bg-background px-3 py-2.5 text-sm" aria-label="اختيار الشركة النشطة"><option value="all">كل الشركات</option>{companies.map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className="rounded-xl border bg-background px-3 py-2.5 text-sm" aria-label="تصفية حالة الطلب"><option value="all">كل الحالات</option>{Object.entries(statusLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><select value={beneficiaryFilter} onChange={(event) => setBeneficiaryFilter(event.target.value)} className="rounded-xl border bg-background px-3 py-2.5 text-sm" aria-label="تصفية المستفيد"><option value="all">كل المستفيدين</option>{beneficiaries.map((beneficiary) => <option key={beneficiary.id} value={beneficiary.id}>{beneficiary.name}</option>)}</select><select value={channelFilter} onChange={(event) => setChannelFilter(event.target.value)} className="rounded-xl border bg-background px-3 py-2.5 text-sm" aria-label="تصفية قناة الصرف"><option value="all">كل قنوات الصرف</option>{channels.map((channel) => <option key={channel.id} value={channel.id}>{channel.name}</option>)}</select><label className="text-xs font-semibold text-muted-foreground"><span className="mb-1 block">من تاريخ</span><input type="date" value={fromDate} onChange={(event) => setFromDate(event.target.value)} className="w-full rounded-xl border bg-background px-3 py-2.5 text-sm" aria-label="من تاريخ"/></label><label className="text-xs font-semibold text-muted-foreground"><span className="mb-1 block">إلى تاريخ</span><input type="date" value={toDate} onChange={(event) => setToDate(event.target.value)} className="w-full rounded-xl border bg-background px-3 py-2.5 text-sm" aria-label="إلى تاريخ"/></label></div>{hasFilters && <div className="mt-4 flex flex-wrap items-center gap-2 text-xs"><span className="rounded-full bg-secondary px-3 py-1.5 font-semibold text-muted-foreground">عرض {filteredRows.length} من {rows.length} طلب</span><button onClick={clearFilters} className="rounded-full border px-3 py-1.5 font-bold text-primary">مسح الفلاتر</button></div>}</div><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-right text-sm"><thead className="bg-secondary/50 text-xs text-muted-foreground"><tr><th className="px-5 py-4 font-bold">الطلب</th><th className="px-5 py-4 font-bold">التاريخ</th><th className="px-5 py-4 font-bold">المستفيد</th><th className="px-5 py-4 font-bold">الشركة</th><th className="px-5 py-4 font-bold">قناة الصرف</th><th className="px-5 py-4 font-bold">المبلغ</th><th className="px-5 py-4 font-bold">الحالة والإجراء</th></tr></thead><tbody className="divide-y">{filteredRows.length ? filteredRows.map((row) => { const action = next[row.status]; const isSelected = selectedRequestId === row.id; return <tr key={row.id} className="cursor-pointer align-top hover:bg-secondary/25" onClick={(event) => { if (!(event.target as HTMLElement).closest("button, input, select, a")) onOpenRequest(row.id); }} onKeyDown={(event) => { if ((event.key === "Enter" || event.key === " ") && event.target === event.currentTarget) { event.preventDefault(); onOpenRequest(row.id); } }} role="button" tabIndex={0} aria-label={`فتح تفاصيل الطلب ${row.referenceNumber}`}><td className="px-5 py-4"><p className="font-bold">{row.title}</p><p className="mt-1 text-xs text-muted-foreground">{row.referenceNumber}</p></td><td className="whitespace-nowrap px-5 py-4 text-xs text-muted-foreground">{new Date(row.scheduledFor ?? row.createdAt ?? 0).toLocaleDateString("ar-SA")}</td><td className="px-5 py-4 font-semibold">{beneficiaryName(row.beneficiaryId)}</td><td className="px-5 py-4">{companyName(row.companyId)}</td><td className="px-5 py-4 text-xs">{channelName(row.channelId)}</td><td className="whitespace-nowrap px-5 py-4 font-display font-bold">{formatCurrencyAmount(row.amount, row.currency, currencies)} <span className="text-xs text-muted-foreground">{row.currency}</span></td><td className="min-w-[220px] px-5 py-4"><span className="inline-flex rounded-full bg-secondary px-2.5 py-1 text-xs font-bold text-primary">{statusLabels[row.status] ?? row.status}</span><div className="mt-3 flex flex-wrap gap-2">{row.status === "review" && canReview && <button disabled={transition.isPending} onClick={() => transition.mutate({ requestId: row.id, toStatus: reviewerAction.status })} className="rounded-xl border border-primary px-3 py-2 text-xs font-bold text-primary disabled:opacity-50">{transition.isPending ? "جارٍ الحفظ…" : reviewerAction.label}</button>}{action && ((row.status === "draft" && canCreate) || (row.status === "review" && canApprove) || (row.status === "approved" && canExecute) || (row.status === "rejected" && canReopen)) && <button disabled={transition.isPending} onClick={() => transition.mutate({ requestId: row.id, toStatus: action.status })} className="rounded-xl bg-primary px-3 py-2 text-xs font-bold text-primary-foreground disabled:opacity-50">{transition.isPending ? "جارٍ الحفظ…" : action.label}</button>}<button onClick={() => setSelectedRequestId(isSelected ? undefined : row.id)} className="rounded-xl border px-3 py-2 text-xs font-bold">{isSelected ? "إخفاء المرفقات" : "المرفقات"}</button></div></td></tr>; }) : <tr><td colSpan={7} className="px-5 py-12 text-center text-sm text-muted-foreground">{rows.length ? "لا توجد نتائج مطابقة للفلاتر الحالية." : "لا توجد طلبات صرف بعد."}</td></tr>}</tbody></table></div>{selectedRequestId && <div className="border-t bg-secondary/30 p-5"><div className="mb-3 text-sm font-bold">مرفقات الطلب المحدد</div><div className="flex flex-col gap-3 sm:flex-row sm:items-center"><input type="file" onChange={(event) => setFile(event.target.files?.[0] ?? null)} className="min-w-0 flex-1 text-xs" accept=".pdf,.png,.jpg,.jpeg,.xlsx,.doc,.docx"/><button disabled={!file || upload.isPending || file.size > 8_000_000} onClick={uploadFile} className="rounded-xl bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground disabled:opacity-50">{upload.isPending ? "جارٍ الرفع…" : "رفع المرفق"}</button></div><div className="mt-3 space-y-2">{attachmentMessage && <p className="text-xs font-semibold text-primary">{attachmentMessage}</p>}{attachments.error && <p className="text-xs font-semibold text-destructive">تعذر تحميل المرفقات: {attachments.error.message}</p>}{(attachments.data ?? []).map((item) => <div key={item.id} className="flex flex-wrap items-center gap-3 text-xs"><span className="font-semibold">{item.fileName} · {Math.ceil(item.sizeBytes / 1024)} كيلوبايت</span><button onClick={() => void openAttachment(item.id, item.fileName, false)} disabled={download.isPending} className="font-bold text-primary disabled:opacity-50">فتح</button><button onClick={() => void openAttachment(item.id, item.fileName, true)} disabled={download.isPending} className="font-bold text-primary disabled:opacity-50">تنزيل</button></div>)}{attachments.isLoading && <p className="text-xs text-muted-foreground">جارٍ تحميل المرفقات…</p>}{!attachments.isLoading && !attachments.error && !(attachments.data ?? []).length && <p className="text-xs text-muted-foreground">لا توجد مرفقات لهذا الطلب.</p>}</div></div>}</div>;
}'''
pattern = r'function RequestWorkflow\(.*?\n109\s+function DataTable'
replacement = new_function + '\nfunction DataTable'
updated, count = re.subn(pattern, replacement, text, count=1, flags=re.S)
if count != 1:
    raise SystemExit(f'expected one RequestWorkflow block, found {count}')
path.write_text(updated)
print('replaced RequestWorkflow:', count)
